  const APPROVAL_LABELS={ot:'ทำงานล่วงเวลา (OT)',expense_transport:'เบิกค่ารถหรือค่าพาหนะ',expense_meal:'เบิกค่าอาหารและเครื่องดื่ม',expense_entertain:'เบิกค่า Entertain',expense_event:'เบิกค่า Event',expense_other:'เบิกค่าใช้จ่ายอื่น ๆ',time_adjust:'ปรับปรุงเวลาเข้า–ออก',shift_change:'เปลี่ยนกะทำงาน',offday_change:'เปลี่ยนกะวันหยุด',document:'ขอเอกสารบริษัท',special_earning:'ขอเงินได้พิเศษหรือรางวัล'};
  const APPROVAL_DAYS=['อาทิตย์','จันทร์','อังคาร','พุธ','พฤหัสบดี','ศุกร์','เสาร์'];
  function approvalFieldMarkup(type){const dayOptions=APPROVAL_DAYS.map((d,i)=>`<option value="${i}">${d}</option>`).join(''),person=employee(activeUserId),shiftOptions=[...new Set([effectiveShift(person).shiftName,...Object.values(settings.departmentShifts||{}).map(x=>x.shiftName)].filter(Boolean))];const shiftMarkup=shiftOptions.map(x=>`<option value="${escapeHTML(x)}">${escapeHTML(x)}</option>`).join('');const month=`<label>เดือนที่เริ่มมีผล<input name="effectiveMonth" type="month" min="${todayISO().slice(0,7)}" value="${todayISO().slice(0,7)}" required></label>`;const date=`<label>วันที่เกี่ยวข้อง<input name="date" type="date" required></label>`;const amount=`<label>จำนวนเงิน (บาท)<input name="amount" type="number" min="0.01" step="0.01" required></label>`;if(type==='ot')return `${date}<label>เวลาเริ่ม OT<input name="startTime" type="time" required></label><label>เวลาสิ้นสุด OT<input name="endTime" type="time" required></label>`;if(type.startsWith('expense_'))return `${date}${type==='expense_other'?'<label>ระบุประเภทค่าใช้จ่าย<input name="customExpenseType" maxlength="80" required></label>':''}${amount}<label>รายละเอียดรายการ/ผู้ร่วมกิจกรรม<input name="expenseDescription" maxlength="300" required></label>`;if(type==='time_adjust')return `${date}<label>เวลาเข้าที่ขอแก้ไข<input name="requestedCheckIn" type="time"></label><label>เวลาออกที่ขอแก้ไข<input name="requestedCheckOut" type="time"></label><p class="form-hint">กรอกเวลาอย่างน้อยหนึ่งช่อง</p>`;if(type==='shift_change')return `${month}<label>กะที่ต้องการ<select name="requestedShift" required>${shiftMarkup}</select></label><p class="form-hint">ขอเปลี่ยนกะได้ไม่เกิน 1 ครั้งต่อเดือน · คำขอรออนุมัติหรือตกลงแล้วจะนับเป็นโควตา</p>`;if(type==='offday_change')return `${month}<label>วันหยุดประจำสัปดาห์วันแรก<select name="offDayOne" required>${dayOptions}</select></label><label>วันหยุดประจำสัปดาห์วันที่สอง<select name="offDayTwo" required>${dayOptions}</select></label><p class="form-hint">เลือกวันหยุดสองวัน (เลือกวันไม่ติดกันได้) · จำกัดคำขอ 1 ครั้งต่อเดือน</p>`;if(type==='document')return `<label>ประเภทเอกสาร<input name="documentType" maxlength="100" placeholder="เช่น หนังสือรับรองการทำงาน" required></label><label>จำนวนฉบับ<input name="documentCopies" type="number" min="1" max="20" value="1" required></label><label>วันที่ต้องการใช้<input name="neededBy" type="date"></label>`;if(type==='special_earning')return `${date}<label>ประเภทรายได้พิเศษ<select name="earningType" required><option value="ค่าคอมมิชชันจากการขาย">ค่าคอมมิชชันจากการขาย</option><option value="เงินรางวัลตามยอดขาย">เงินรางวัลตามยอดขาย</option><option value="เงินพิเศษจากไลฟ์สด">เงินพิเศษจากไลฟ์สด/กิจกรรมขาย</option><option value="อื่น ๆ">อื่น ๆ</option></select></label><label>ยอดขาย/ฐานคำนวณ (บาท)<input name="earningBase" type="number" min="0" step="0.01" required></label><label>อัตราเปอร์เซ็นต์ (%)<input name="earningRate" type="number" min="0" max="100" step="0.01" value="1" required></label><p class="form-hint">ระบบคำนวณยอดเบื้องต้นจากฐาน × อัตรา ผู้อนุมัติและ HR ต้องตรวจสอบก่อนบันทึกเงินได้</p>`;return '';}
  function updateApprovalTypeFields(){const type=$("#approvalType").value,container=$("#approvalTypeFields"),details=$("#approvalDetails"),detailsLabel=$(".approval-details-label");container.innerHTML=approvalFieldMarkup(type)||"<p class=\"form-hint\">เลือกรายการเพื่อแสดงข้อมูลที่ต้องกรอก</p>";const optional=type==="offday_change";details.required=!!type&&!optional;details.placeholder=optional?"อธิบายเพิ่มเติมได้ถ้ามี (ไม่บังคับ)":"อธิบายเหตุผลหรือข้อมูลประกอบคำขอ";if(detailsLabel.firstChild)detailsLabel.firstChild.textContent=optional?"รายละเอียดเพิ่มเติม (ไม่บังคับ)":"รายละเอียดเพิ่มเติม";$("#approvalAttachments").required=type.startsWith("expense_")||type==="special_earning";$("#otApprovalNotice").hidden=type!=="ot";$("#specialEarningEstimate").hidden=type!=="special_earning";}function updateEarningEstimate(){const base=Number($('[name="earningBase"]')?.value)||0,rate=Number($('[name="earningRate"]')?.value)||0;$('#specialEarningEstimateValue').textContent=new Intl.NumberFormat(uiLocale(),{style:'currency',currency:'THB'}).format(base*rate/100);}
  async function submitApprovalRequest(ev){
    ev.preventDefault();
    if(isHRSession()){showToast('บัญชี HR ไม่สามารถส่งคำขอในนามพนักงานได้',true);return;}
    const person=employee(activeUserId),type=$('#approvalType').value,details=$('#approvalDetails').value.trim();
    if(!person||person.status!=='active'||!type||!APPROVAL_LABELS[type]){showToast('กรุณาเลือกประเภทคำขอและตรวจสอบบัญชีพนักงาน',true);return;}
    const fields=Object.fromEntries([...$('#approvalTypeFields').querySelectorAll('[name]')].map(input=>[input.name,input.value.trim()]));
    if(type==='time_adjust'&&!fields.requestedCheckIn&&!fields.requestedCheckOut){showToast('กรุณาระบุเวลาเข้าใหม่หรือเวลาออกใหม่อย่างน้อยหนึ่งช่อง',true);return;}
    if(type==='offday_change'&&fields.offDayOne===fields.offDayTwo){showToast('กรุณาเลือกวันหยุดสองวันที่ไม่ซ้ำกัน',true);return;}
    if(type==='special_earning')fields.calculatedAmount=(Number(fields.earningBase||0)*Number(fields.earningRate||0)/100).toFixed(2);
    if(['shift_change','offday_change'].includes(type)){const month=fields.effectiveMonth,existing=approvalRequests.some(x=>x.employeeId===person.id&&x.type===type&&x.fields?.effectiveMonth===month&&x.status!=='ไม่อนุมัติ');if(existing){showToast('เดือนที่เลือกมีคำขอประเภทนี้อยู่แล้ว',true);return;}}
    let attachments=[];try{attachments=await readRequestAttachments($('#approvalAttachments').files);}catch(error){showToast(error.message||'อ่านไฟล์แนบไม่สำเร็จ',true);return;}
    const request={id:crypto.randomUUID?crypto.randomUUID():`${Date.now()}-${Math.random()}`,type,employeeId:person.id,employeeCode:person.code,employeeName:person.name,department:person.department,fields,details,attachments,status:'รออนุมัติ',createdAt:new Date().toISOString()};
    approvalRequests.push(request);if(!saveAll()){approvalRequests.pop();return;}
    $('#approvalRequestForm').reset();$('#approvalTypeFields').innerHTML='<p class="form-hint">เลือกประเภทคำขอเพื่อแสดงข้อมูลที่ต้องกรอก</p>';updateApprovalTypeFields();renderApprovalRequests();renderEmployeeDashboard();renderEmployeeHome();showToast('ส่งคำขอแล้ว รอผู้อนุมัติพิจารณา');
  }
  function readRequestAttachments(files){const list=[...files];if(list.length>3)throw new Error('แนบไฟล์ได้สูงสุด 3 ไฟล์');const allowed=['application/pdf','image/png','image/jpeg','image/webp'];if(list.some(f=>!allowed.includes(f.type)))throw new Error('รองรับเฉพาะ PDF, PNG, JPG และ WEBP');if(list.reduce((n,f)=>n+f.size,0)>2*1024*1024)throw new Error('ขนาดไฟล์รวมต้องไม่เกิน 2 MB');return Promise.all(list.map(file=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve({name:file.name,type:file.type,data:reader.result});reader.onerror=()=>reject(new Error('อ่านไฟล์แนบไม่สำเร็จ'));reader.readAsDataURL(file);})));}
  function approvalAttachmentsMarkup(files){return (files||[]).map(a=>{if(!['application/pdf','image/png','image/jpeg','image/webp'].includes(a.type)||!String(a.data||'').startsWith(`data:${a.type};base64,`))return '';return `<a class="approval-file-link" href="${a.data}" target="_blank" rel="noopener noreferrer">${escapeHTML(a.name||'ไฟล์แนบ')} ↗</a>`;}).filter(Boolean).join(' ' )||'—';}
function announcementAttachmentMarkup(files){return (files||[]).map(a=>{if(!['application/pdf','image/png','image/jpeg','image/webp'].includes(a.type)||!String(a.data||'').startsWith(`data:${a.type};base64,`))return '';const name=escapeHTML(a.name||'ไฟล์แนบ');return `<div class="announcement-file-actions"><a class="approval-file-link" href="${a.data}" target="_blank" rel="noopener noreferrer">เปิด ${name} ↗</a><a class="approval-file-link" href="${a.data}" download="${name}">ดาวน์โหลด ${name} ↓</a></div>`;}).filter(Boolean).join('');}
  function approvalFieldsMarkup(fields){const names={date:'วันที่',startTime:'เริ่ม OT',endTime:'สิ้นสุด OT',amount:'จำนวนเงิน',expenseDescription:'รายการ',customExpenseType:'ประเภทอื่น',requestedCheckIn:'เวลาเข้าใหม่',requestedCheckOut:'เวลาออกใหม่',effectiveMonth:'เดือนเริ่มมีผล',requestedShift:'กะที่ขอ',offDayOne:'วันหยุด 1',offDayTwo:'วันหยุด 2',documentType:'เอกสาร',documentCopies:'จำนวนฉบับ',neededBy:'วันที่ต้องการ',earningType:'ประเภทรายได้',earningBase:'ฐานคำนวณ',earningRate:'อัตรา (%)',calculatedAmount:'ยอดคำนวณ (บาท)'};return Object.entries(fields||{}).map(([k,v])=>`${escapeHTML(names[k]||k)}: ${escapeHTML(k==='offDayOne'||k==='offDayTwo'?APPROVAL_DAYS[Number(v)]||v:v)}`).join(' · ')||'—';}
