  function announcementRelatedPeriod(item){const start=item.relatedStart||'',end=item.relatedEnd||'',startTime=item.relatedStartTime||'',endTime=item.relatedEndTime||'';if(!start&&!end&&!startTime&&!endTime)return '—';const dates=!start&&!end?'':start&&end&&start===end?announcementDateText(start):start&&end?`${announcementDateText(start)} – ${announcementDateText(end)}`:announcementDateText(start||end),times=startTime&&endTime?`เวลา ${startTime}–${endTime} น.`:startTime?`เริ่มเวลา ${startTime} น.`:endTime?`สิ้นสุดเวลา ${endTime} น.`:'';return [dates,times].filter(Boolean).join(' · ');}
  function renderAnnouncements(){const body=$('#announcementListBody');if(!body)return;const now=new Date();body.replaceChildren();announcements.slice().sort((a,b)=>String(b.displayStart||'').localeCompare(String(a.displayStart||''))).forEach(item=>{const tr=document.createElement('tr'),relevant=announcementRelatedPeriod(item),actions=`<button class="mini-action" data-announcement-edit="${escapeHTML(item.id)}">แก้ไข</button> <button class="mini-action delete" data-announcement-delete="${escapeHTML(item.id)}">ลบ</button>`;tr.innerHTML=`<td><b>${escapeHTML(item.title)}</b><small class="approval-meta">${escapeHTML(item.createdBy||'')}</small></td><td>${escapeHTML(relevant)}</td><td>${escapeHTML(announcementDateTimeText(item.displayStart))}<br>ถึง ${escapeHTML(announcementDateTimeText(item.displayEnd))}</td><td><span class="status-pill ${announcementStatusLabel(item,now)==='กำลังแสดง'?'status-working':item.status==='published'?'status-absent':'status-neutral'}">${escapeHTML(announcementStatusLabel(item,now))}</span></td><td>${(item.attachments||[]).length} ไฟล์</td><td>${actions}</td>`;body.append(tr);});$('#announcementListEmpty').hidden=announcements.length>0;}
