  function renderEmployeeAnnouncementList(){const list=$('#employeeAnnouncementList');if(!list)return;const now=new Date(),mode=$("#employeeAnnouncementFilter").value||'active',items=announcements.filter(x=>{const start=dateTime(x.displayStart),end=dateTime(x.displayEnd);if(x.status!=='published'||!start||!end)return false;if(mode==='all')return true;if(mode==='history')return end<now;return now>=start&&now<=end;}).sort((a,b)=>String(a.displayStart).localeCompare(String(b.displayStart)));list.replaceChildren();items.forEach(item=>{const card=document.createElement('article');card.className='panel employee-announcement-card';const image=item.image?`<img class="employee-announcement-card-image" src="${escapeHTML(new URL(item.image,document.baseURI).href)}" alt="ภาพประกอบประกาศ">`:'';card.innerHTML=`${image}<div class="employee-announcement-card-body"><div class="eyebrow">ประกาศจากบริษัท</div><h2>${escapeHTML(item.title)}</h2>${announcementRelevantMetaMarkup(item)}<p>${escapeHTML(item.content)}</p><small>เผยแพร่ ${escapeHTML(announcementDateTimeText(item.displayStart))}</small></div>`;list.append(card);});$('#employeeAnnouncementListEmpty').hidden=items.length>0;}  function showEmployeeAnnouncementQueue(){if(isHRSession()||!employee(activeUserId)||$('#appShell').hidden)return;const now=new Date();announcementQueue=announcements.filter(x=>x.status==='published'&&dateTime(x.displayStart)&&dateTime(x.displayEnd)&&now>=dateTime(x.displayStart)&&now<=dateTime(x.displayEnd)).sort((a,b)=>String(a.displayStart).localeCompare(String(b.displayStart)));announcementQueueIndex=0;if(!announcementQueue.length)return;renderEmployeeAnnouncementPopup();const dialog=$('#employeeAnnouncementDialog');if(!dialog.open)dialog.showModal();}
